const groupOf = code => String(code).replace(/\d+$/,"");
const bayOf   = code => String(code)[0];
function bayBounds(bay){
  const cs=comps().filter(c=>bayOf(c.code)===bay);
  if(!cs.length)return null;
  const x=Math.min(...cs.map(c=>c.x)), y=Math.min(...cs.map(c=>c.y));
  return {side:cs[0].side, x, y,
    w:Math.max(...cs.map(c=>c.x+c.w))-x, h:Math.max(...cs.map(c=>c.y+c.h))-y, n:cs.length};
}
