const GUIDEITEMS=[["Magnetic fingerprint powder","C","Reagent",["Use on non-metal surfaces only: paper, wood, tile, glass.","Do not use on metal.","Do not use on a wet surface. Powder and moisture turn to paste — let it dry or use another method.","Pour a small amount onto a plate or an evidence envelope folded like a plate. Never dip the applicator into the container.","Apply with the magnetic applicator only.","Lift onto a white backing card."]],["Black fingerprint powder","C","Reagent",["Use on light-coloured surfaces: light paper, wood, tile, glass, metals.","Lift onto a white backing card. The card is always the opposite colour to the powder.","Apply with the fiberglass brush.","Pour a small amount onto a plate or a folded evidence envelope. Never dip the brush into the container.","Do not use on a wet surface."]],["White fingerprint powder","C","Reagent",["Use on dark-coloured surfaces: dark paper, wood, tile, glass, metals.","Lift onto a black backing card. The card is always the opposite colour to the powder.","Apply with the fiberglass brush.","Pour a small amount onto a plate or a folded evidence envelope. Never dip the brush into the container.","Do not use on a wet surface."]],["Copper fingerprint powder","C","Reagent",["Carried in the kit as an alternative when black and white give poor contrast.","Match the powder to the surface: the powder must contrast with the surface, and the backing card must contrast with the powder.","Pour a small amount onto a plate or a folded evidence envelope. Never dip the brush into the container.","Do not use on a wet surface."]],["Silver black fingerprint powder","C","Reagent",["Do not use. Carried in the kit but not to be used.","Use black powder on light surfaces or white powder on dark surfaces instead."]],["Magnetic applicator","C","Durable",["For magnetic powder only.","Load from powder poured onto a plate or folded envelope, never from the container.","Clean between surfaces."]],["Fiberglass brush","C","Durable",["For applying white and black powder.","Load from powder poured onto a plate or folded envelope, never from the container.","Do not use on a wet surface."]],["Feather duster","C","Durable",["For removing small amounts of excess powder from a print before lifting.","Never dip it into a powder container."]],["Hinge lifters","C","Consumable",["Lift the developed print, then fold the hinge over onto the backing card.","Backing card is the opposite colour to the powder used: white card for black or magnetic powder, black card for white powder.","Label the lift with the location it came from and the surface."]],["Gel lifters","C","Consumable",["For lifting from textured or curved surfaces where tape will not sit flat.","Photograph the lift before packaging.","Label with the location and surface it came from."]],["Lifting tape","C","Consumable",["For flat surfaces. Lay the tape down without trapping air, lift in one movement.","Transfer to a backing card of the opposite colour to the powder.","Label with the location and surface it came from."]],["Backing cards, white","C","Consumable",["Used with black powder and with magnetic powder.","The card is always the opposite colour to the powder so the lift still reads."]],["Backing cards, black","C","Consumable",["Used with white powder.","The card is always the opposite colour to the powder so the lift still reads."]],["Cotton swabs, DNA","D","Consumable",["Collect with one wet swab and one dry swab from the same area.","One sample per envelope. DNA from different areas of the scene never shares an envelope.","Name the exact surface swabbed on the envelope, not just the room.","Elimination DNA is required before the swabs can be tested if there is a known victim."]],["Buccal swab kit","D","Consumable",["For known samples and elimination DNA.","One sample per envelope.","Elimination DNA is required before scene swabs can be tested if there is a known victim."]],["GSR / SEM kit","E","Consumable",["Record a separate time for every sample site.","Sites are taken as right back, right palm, left back, left palm.","Write each site and its time on the envelope, for example: right back 0943 hrs, right palm 0945 hrs.","Note where the kit was collected, including at autopsy."]],["Red evidence envelopes","H","Consumable",["General evidence. Anything that is not drugs and fits in an envelope.","Write the description on the envelope first, then copy it into EFORCE word for word.","The description answers four things: what and how many, which evidence marker, where exactly, and when plus your item number.","Write the EFORCE tag number on the envelope once it is issued."]],["Blue evidence envelopes","H","Consumable",["Suspected drugs only. Nothing else goes in a blue envelope.","Suspected drugs must not go in a red envelope.","Write the EFORCE tag number on the envelope once it is issued."]],["Brown paper bags","H","Consumable",["For items too large for a normal envelope.","Place a red evidence sticker on the bag and label the sticker.","For clothing and lab items, state what the item is packaged in — the lab will not accept a submission without it."]],["Red evidence stickers","H","Consumable",["Applied to brown paper bags and any container that is not a pre-printed envelope.","Label the sticker the same way you would label an envelope."]],["Sharps container","H","Consumable",["Knives and other sharp or pointed objects.","If it could cut somebody handling it later, it goes in a sharps container, not an envelope."]],["Gun box","G","Consumable",["Unload the firearm. It goes into the box unloaded.","If it is a pistol, lock the slide back before boxing.","Zip-tie the firearm to the box so it cannot shift.","Draw an arrow on the printed firearm picture on the outside of the box showing which way the firearm faces inside.","Do not put ammunition in the gun box. Ammunition is packaged separately with its own EFORCE entry.","Check the chamber and the magazine before the box is closed.","EFORCE comment needs: date and time collected, status of the firearm, round count, whether one was chambered, and where it was found."]],["Small plastic baggies, casings","G","Consumable",["Each casing goes into its own small baggie.","All of the baggies then go into one red evidence envelope.","Label the envelope with how many casings are inside and the casing information."]],["Bullet boxes, cotton lined","G","Consumable",["A recovered bullet or fragment goes into a small brown box with cotton lining.","The box then goes into a red evidence envelope."]],["Dry safe","H","Durable",["For wet clothing. Wet items never go into evidence envelopes.","Follow the instructions posted on the dry safe itself."]],["Latex gloves","A","Consumable",["Worn any time you handle evidence. Wear two pairs.","The first pair stays on while you collect. Change the outer pair between items, not just when it looks dirty.","Two pairs keep your own prints and DNA off the evidence.","Patrol gloves are not PPE. They protect neither you nor the evidence."]],["Crime scene tape","A","Consumable",["Set the perimeter larger than you believe the scene is. You can bring it in later; you cannot re-secure ground people have walked through.","If you are not sure where the edge of the scene is, put the tape further out.","Everyone who crosses the tape goes on the scene entry log, including you."]],["Evidence markers","B","Durable",["Set the marker next to the item. Never move evidence to place a marker — if placing it there would move the item, set it further away.","The marker number you use is the number that goes on the envelope and in your photographs.","Some markers have a scale built in; use it for close-up shots."]],["Temporary evidence markers","B","Consumable",["Placed on arrival to keep people off possible evidence until the real markers reach the scene.","Do not move evidence to place one."]],["L-scale","B","Durable",["Used in every close-up photograph.","It gives size in both directions, and the targets let the lab correct for camera angle.","Use the marker's built-in scale or a scale from the evidence collection box."]],["Scene camera","B","Durable",["Check it before you need it: charged, and no files left on the card.","Photograph in four ranges in order: overall, mid, close, then close-up with scale.","Overall: start wide, include street signs or the address so the photos tie to a location.","Mid: buildings and obvious evidence, overlapping every frame so positions relate to each other.","Close: the item filling the frame, still in place.","Close-up with scale: the same shot with a scale beside it.","Get the overall shots early, before more people arrive and add to the scene.","Back at the station, move the photographs off the card and delete them from the camera card."]]];
function seedGuideItems(){
  let added=0;
  GUIDEITEMS.forEach(([name,cat,cls,steps])=>{
    if(S.items.some(i=>String(i.name).toLowerCase()===name.toLowerCase()))return;
    S.items.push({id:newId(),name,loc:"",cat,cls,qty:0,par:"",date:"",
      status:"Stocked",gapType:"",note:"",steps:steps.slice(),source:GUIDESRC,
      verified:"",uses:[],rel:[],links:[],fav:false});
    added++;
  });
  return added;
}
const STOCKV=7;
function seedForms(){
  STOCKFORMS.forEach(t=>{
    const have=S.forms.find(f=>f.name===t.name);
    if(have){
      have.stock=true;                       // shipped with the app, so it cannot be deleted
      // refresh the built-in definition unless it has been edited by hand
      if(!have.edited){have.fields=parseFields(t.fields);have.desc=t.desc;have.rev=t.rev}
      return;
    }
    S.forms.push({id:newId(),name:t.name,cat:t.cat,rev:t.rev,desc:t.desc,
      stock:true,verified:"",fields:parseFields(t.fields)});
  });
}
