/* ---------- github sync ---------- */
if(!S.gh)S.gh={owner:"",repo:"",path:"data.json",token:"",sha:"",last:""};
let dirty=false, pushT=null, conflict=false, syncErr="";

const b64enc=s=>{const b=new TextEncoder().encode(s);let out="";
  for(let i=0;i<b.length;i+=8192)out+=String.fromCharCode.apply(null,b.subarray(i,i+8192));
  return btoa(out)};
const b64dec=s=>new TextDecoder().decode(Uint8Array.from(atob(s.replace(/\s/g,"")),c=>c.charCodeAt(0)));
const ghOn=()=>!!(S.gh.owner&&S.gh.repo&&S.gh.token);
const ghURL=()=>`https://api.github.com/repos/${S.gh.owner}/${S.gh.repo}/contents/${S.gh.path||"data.json"}`;
const ghHead=()=>({Authorization:"Bearer "+S.gh.token,Accept:"application/vnd.github+json",
  "X-GitHub-Api-Version":"2022-11-28"});
let storageState={asked:false,persisted:false,used:0,quota:0};
async function claimStorage(){
  try{
    if(navigator.storage&&navigator.storage.persisted){
      storageState.persisted=await navigator.storage.persisted();
      if(!storageState.persisted&&navigator.storage.persist)
        storageState.persisted=await navigator.storage.persist();
    }
    if(navigator.storage&&navigator.storage.estimate){
      const e=await navigator.storage.estimate();
      storageState.used=e.usage||0; storageState.quota=e.quota||0;
    }
  }catch(e){}
  storageState.asked=true;
  if(view==="data")renderData();
}
const payload=()=>({items:S.items,comps:S.comps,forms:S.forms.map(f=>{
    const c=Object.assign({},f);delete c.fills;return c}),walls:S.walls,demo:S.demo,
  lastCat:S.lastCat,lastCls:S.lastCls,savedAt:new Date().toISOString()});

async function ghPull(silent){
  if(!ghOn())return;
  try{
    const r=await fetch(ghURL()+"?ref=HEAD&t="+Date.now(),{headers:ghHead(),cache:"no-store"});
    if(r.status===404){S.gh.sha="";store.set(S);if(!silent)toast("No data file yet — push to create it");return"empty"}
    if(!r.ok)throw new Error(r.status===401?"Token rejected":r.status===403?"No access to that repo":"GitHub error "+r.status);
    const j=await r.json(), o=JSON.parse(b64dec(j.content));
    S.items=o.items||[];S.comps=o.comps||[];S.forms=o.forms||[];if(o.walls)S.walls=o.walls;S.demo=!!o.demo;
    S.gh.sha=j.sha;S.gh.last=new Date().toISOString();dirty=false;conflict=false;
    syncErr="";retries=0;clearTimeout(pushT);store.set(S);renderSyncBar();
    if(!silent)toast("Pulled "+S.items.length+" items");render();return"ok";
  }catch(e){if(!silent)toast(e.message||"Pull failed");return"error"}
}
async function ghPush(force){
  if(!ghOn())return;
  try{
    const body={message:"Van inventory — "+new Date().toISOString().slice(0,16).replace("T"," "),
      content:b64enc(JSON.stringify(payload(),null,1))};
    if(S.gh.sha&&!force)body.sha=S.gh.sha;
    else if(force){const r0=await fetch(ghURL(),{headers:ghHead(),cache:"no-store"});
      if(r0.ok){const j0=await r0.json();body.sha=j0.sha}}
    const r=await fetch(ghURL(),{method:"PUT",headers:Object.assign({"Content-Type":"application/json"},ghHead()),
      body:JSON.stringify(body)});
    if(r.status===409||r.status===422){conflict=true;store.set(S);renderData();
      return toast("Someone else changed the data — see Sync")}
    if(!r.ok)throw new Error(r.status===401?"Token rejected":r.status===403?"No write access":"GitHub error "+r.status);
    const j=await r.json();S.gh.sha=j.content.sha;S.gh.last=new Date().toISOString();
    dirty=false;conflict=false;syncErr="";retries=0;store.set(S);
    renderSyncBar();renderData();return"ok";
  }catch(e){
    syncErr=e.message||"Couldn't reach GitHub";
    store.set(S);renderSyncBar();
    clearTimeout(pushT);pushT=setTimeout(()=>ghPush(false),retryIn());
    return "error"}
}
let retries=0;
function retryIn(){retries=Math.min(retries+1,6);return Math.min(60000,2000*Math.pow(2,retries-1))}
function queuePush(){ if(!ghOn())return; dirty=true; retries=0;
  clearTimeout(pushT); pushT=setTimeout(()=>ghPush(false),2500);
  renderSyncPill(); renderSyncBar(); }
function renderSyncBar(){
  const b=$("#syncbar"); if(!b)return;
  const offline=typeof navigator!=="undefined"&&navigator.onLine===false;
  if(!ghOn()||(!dirty&&!syncErr&&!conflict)){b.style.display="none";b.innerHTML="";fitHeader();return}
  let msg,cls;
  if(conflict){cls="bad";msg="Another device changed the data. Open Sync to choose which version wins."}
  else if(offline){cls="warn";msg="No connection. Your changes are saved on this phone and will push when you're back online."}
  else if(syncErr){cls="bad";msg=syncErr+". Retrying — your changes are still saved on this phone."}
  else {b.style.display="none";b.innerHTML="";fitHeader();return}
  b.className="demobar "+cls; b.style.display="";
  b.innerHTML=`<span>${esc(msg)}</span><button id="syncnow">${conflict?"Open Sync":"Retry"}</button>`;
  fitHeader();
}
function renderSyncPill(){
  const el=$("#syncpill"); if(!el)return;
  el.textContent=conflict?"Conflict":dirty?"Saving…":S.gh.last?"Synced "+S.gh.last.slice(11,16):"Not synced";
  el.className="syncpill"+(conflict?" bad":dirty?" busy":"");
}

