  const qa=e.target.closest("[data-qa]");
  if(qa){S.quick=qa.dataset.qa==="1";save();renderSweep();
    const f=$("#q-name")||$("#f-name"); f&&f.focus(); return}
  if(e.target.closest("#qadd"))return quickAdd();
  const ju=e.target.closest("[data-undo]");
